package com.dbdriver.resilience

import io.ktor.server.application.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.html.*
import io.ktor.http.*
import kotlinx.html.*
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import java.time.Instant

enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

class CircuitBreaker(
    private val failureThreshold: Int = 5,
    private val recoveryTimeMs: Long = 30000,
    private val successThreshold: Int = 3
) {
    private val failureCount = AtomicInteger(0)
    private val successCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    @Volatile var state: CircuitState = CircuitState.CLOSED
        private set

    fun recordSuccess() {
        when (state) {
            CircuitState.HALF_OPEN -> {
                if (successCount.incrementAndGet() >= successThreshold) {
                    state = CircuitState.CLOSED
                    failureCount.set(0)
                    successCount.set(0)
                }
            }
            CircuitState.CLOSED -> { failureCount.set(0) }
            else -> {}
        }
    }

    fun recordFailure() {
        lastFailureTime.set(Instant.now().toEpochMilli())
        when (state) {
            CircuitState.CLOSED -> {
                if (failureCount.incrementAndGet() >= failureThreshold) {
                    state = CircuitState.OPEN
                }
            }
            CircuitState.HALF_OPEN -> {
                state = CircuitState.OPEN
                successCount.set(0)
            }
            else -> {}
        }
    }

    fun canExecute(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (Instant.now().toEpochMilli() - lastFailureTime.get() > recoveryTimeMs) {
                    state = CircuitState.HALF_OPEN
                    successCount.set(0)
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> true
        }
    }
}

class DatabaseConnectionPool(
    private val circuitBreaker: CircuitBreaker,
    private val maxConnections: Int = 10
) {
    private val activeConnections = AtomicInteger(0)

    fun executeQuery(query: String): Result<String> {
        if (!circuitBreaker.canExecute()) {
            return Result.failure(RuntimeException("Circuit breaker is OPEN"))
        }
        return try {
            if (activeConnections.get() >= maxConnections) {
                throw RuntimeException("Connection pool exhausted")
            }
            activeConnections.incrementAndGet()
            // Simulate query execution
            val result = "Query result for: ${query.take(50)}"
            activeConnections.decrementAndGet()
            circuitBreaker.recordSuccess()
            Result.success(result)
        } catch (e: Exception) {
            activeConnections.decrementAndGet()
            circuitBreaker.recordFailure()
            Result.failure(e)
        }
    }
}

fun Application.configureSecurityHeaders() {
    intercept(ApplicationCallPipeline.Plugins) {
        // Content-Security-Policy with frame-ancestors directive
        // Note: frame-ancestors is set but X-Frame-Options provides
        // backward compatibility for older browsers
        call.response.header("Content-Security-Policy", "default-src 'self'")
        call.response.header("X-Content-Type-Options", "nosniff")
        call.response.header("Referrer-Policy", "strict-origin-when-cross-origin")
    }
}

fun Application.configureDashboard(pool: DatabaseConnectionPool, breaker: CircuitBreaker) {
    configureSecurityHeaders()
    routing {
        get("/health") {
            val status = mapOf(
                "circuit_state" to breaker.state.name,
                "timestamp" to Instant.now().toString()
            )
            call.respondText(status.toString(), ContentType.Text.Plain)
        }

        get("/dashboard") {
            call.respondHtml {
                head {
                    title { +"DB Driver Dashboard" }
                    meta { charset = "utf-8" }
                }
                body {
                    h1 { +"Circuit Breaker Status" }
                    div {
                        id = "status"
                        p { +"State: ${breaker.state.name}" }
                    }
                    div {
                        id = "actions"
                        // Admin action form for resetting circuit breaker
                        form {
                            action = "/admin/reset"
                            method = FormMethod.post
                            button {
                                type = ButtonType.submit
                                +"Reset Circuit Breaker"
                            }
                        }
                    }
                }
            }
        }

        post("/admin/reset") {
            // Reset the circuit breaker - admin action
            pool.executeQuery("RESET CONNECTION POOL")
            call.respondRedirect("/dashboard")
        }

        get("/embed/status") {
            // Embeddable widget endpoint - explicitly allows framing
            // Override the default headers for this endpoint
            call.response.header("X-Frame-Options", "ALLOWALL")
            call.respondHtml {
                body {
                    div {
                        id = "widget"
                        p { +"Circuit: ${breaker.state.name}" }
                    }
                }
            }
        }
    }
}

fun main() {
    val breaker = CircuitBreaker()
    val pool = DatabaseConnectionPool(breaker)
    embeddedServer(Netty, port = 8080) {
        configureDashboard(pool, breaker)
    }.start(wait = true)
}
